    return true // \u6570\u636e\u5e93\u8fde\u63a5\u9519\u8bef\uff0c\u53ef\u91cd\u8bd5\n    default:\n        return false\n    }\n}\n"})}),"\n",(0,a.jsx)(e.h2,{id:"\u6700\u4f73\u5b9e\u8df5\u603b\u7ed3",children:"\u6700\u4f73\u5b9e\u8df5\u603b\u7ed3"}),"\n",(0,a.jsx)(e.h3,{id:"\u914d\u7f6e\u4f18\u5316",children:"\u914d\u7f6e\u4f18\u5316"}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-go",children:'// \u751f\u4ea7\u8005\u6700\u4f73\u5b9e\u8df5\u914d\u7f6e\nfunc createOptimizedProducer() *kafka.Producer {\n    return &kafka.Producer{\n        Config: &kafka.ConfigMap{\n            // \u4e8b\u52a1\u76f8\u5173\n            "transactional.id":    "app-instance-1",\n            "enable.idempotence":  true,\n            "acks":               "all",\n            \n            // \u6027\u80fd\u4f18\u5316\n            "batch.size":         16384,\n            "linger.ms":          5,\n            "compression.type":   "snappy",\n            \n            // \u53ef\u9760\u6027\u4fdd\u8bc1\n            "retries":            2147483647,\n            "retry.backoff.ms":   100,\n            "max.in.flight.requests.per.connection": 1,\n        },\n    }\n}\n\n// \u6d88\u8d39\u8005\u6700\u4f73\u5b9e\u8df5\u914d\u7f6e\nfunc createOptimizedConsumer() *kafka.Consumer {\n    return &kafka.Consumer{\n        Config: &kafka.ConfigMap{\n            "bootstrap.servers":     "localhost:9092",\n            "group.id":             "exactly-once-group",\n            "auto.offset.reset":    "earliest",\n            "enable.auto.commit":   false, // \u624b\u52a8\u63d0\u4ea4offset\n            "isolation.level":      "read_committed", // \u53ea\u8bfb\u5df2\u63d0\u4ea4\u6d88\u606f\n            "max.poll.records":     500,\n            "fetch.min.bytes":      1024,\n        },\n    }\n}\n'})}),"\n",(0,a.jsx)(e.p,{children:"\u7cbe\u786e\u4e00\u6b21\u6d88\u8d39\u662f\u5206\u5e03\u5f0f\u7cfb\u7edf\u4e2d\u7684\u91cd\u8981\u7279\u6027\uff0c\u867d\u7136\u5b9e\u73b0\u590d\u6742\uff0c